package ama.governance;
import ama.contract.GovernanceContracts.*;
import ama.contract.IdentityContracts.Actor;
import ama.contract.MeetingContracts.Conflict;
import ama.access.MeetingAccess.AccessDeniedException;
import ama.db.TransactionRunner;
import ama.meeting.JdbcMeetingAccess;
import javax.sql.DataSource;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
/** Governance has its own resources. No method grants or edits a meeting ACL. */
public final class JdbcGovernance extends JdbcOperationsSupport {
 private final GovernanceModelPort model;private final EncryptedEmbeddingStore crypto;
 private static final String VOICE="id,subject_id subjectId,consent_reference consentReference,purpose,model_version modelVersion,dimension,sample_count sampleCount,DATE_FORMAT(expires_at,'%Y-%m-%dT%H:%i:%s.%fZ') expiresAt,state,CAST(revision AS CHAR) revisionToken,review_reason reviewReason";
 public JdbcGovernance(DataSource source,TransactionRunner tx,JdbcMeetingAccess access,GovernanceModelPort model,EncryptedEmbeddingStore crypto){super(source,tx,access);this.model=model;this.crypto=crypto;}
 public Map<String,Object> enroll(Actor actor,String key,String consent,String expires,byte[] wav){
  reason(consent);long count=GovernanceAudio.require(wav,48000,480000);Instant deadline;try{deadline=Instant.parse(expires).truncatedTo(java.time.temporal.ChronoUnit.MICROS);}catch(RuntimeException bad){throw new IllegalArgumentException("Consent expiry required");}
  String sha=sha(wav);var request=Map.of("consent",consent,"expires",deadline.toString(),"sha",sha);var config=tx.required(()->{active(actor);return currentConfig();});
  // Return the original receipt before expensive inference, while retaining current identity checks.
  String receiptScope=digest("operations-v1",actor.enterpriseId(),"VOICE_ENROLL",key);var previous=tx.required(()->{active(actor);var rows=j.queryForList("SELECT request_hash,CAST(result_json AS CHAR) result FROM governance_command WHERE scope_hash=?",receiptScope);if(rows.isEmpty())return null;var row=rows.getFirst();if(!digest(write(request)).equals(row.get("request_hash")))throw new Conflict();return row.get("result") instanceof String result?map(result):null;});if(previous!=null)return previous;
  if(!deadline.isAfter(Instant.now())||deadline.isAfter(Instant.now().plus(Duration.ofDays(365))))throw new IllegalArgumentException("Consent expires in 1 to 365 days");

  var embedding=model.embed(wav,config.modelVersion());if(!embedding.modelVersion().equals(config.modelVersion()))throw new IllegalArgumentException("Pinned embedding model required");
  return command(actor,key,"VOICE_ENROLL",request,false,()->{String id=UUID.randomUUID().toString();byte[] encrypted=crypto.encrypt(aad(id,actor.enterpriseId(),embedding.modelVersion(),embedding.dimension()),embedding);
   j.update("INSERT INTO governed_voiceprint(id,subject_id,consent_reference,purpose,model_version,dimension,sample_sha,sample_count,expires_at,state,encrypted_embedding) VALUES (?,?,?,'SPEAKER_CANDIDATE',?,?,?,?,?,'PENDING',?)",id,actor.enterpriseId(),consent,embedding.modelVersion(),embedding.dimension(),sha,count,Timestamp.from(deadline),encrypted);voiceHistory(actor,id,0,"PENDING",consent);audit(actor,"VOICEPRINT_CONSENTED",id,0);return voice(id);});
 }
 public Map<String,Object> reviewVoice(Actor actor,String id,String key,long expected,String decision,String reason){
  id(id);expected(expected);reason(reason);if(!Set.of("APPROVED","REJECTED").contains(decision))throw new IllegalArgumentException("Explicit review required");
  return command(actor,key,"VOICE_REVIEW",List.of(id,expected,decision,reason),true,()->{var row=lockedVoice(id);if(!"PENDING".equals(row.get("state"))||expected!=((Number)row.get("revision")).longValue()||!instant(row.get("expires_at")).isAfter(Instant.now()))throw new Conflict();if(actor.enterpriseId().equals(row.get("subject_id")))throw new AccessDeniedException();
   if(!"ACTIVE".equals(j.queryForObject("SELECT status FROM enterprise_identity WHERE enterprise_id=? FOR SHARE",String.class,row.get("subject_id"))))throw new AccessDeniedException();
   j.update("UPDATE governed_voiceprint SET state=?,revision=revision+1,reviewer_id=?,review_reason=?,encrypted_embedding=IF(?='REJECTED',NULL,encrypted_embedding),updated_at=UTC_TIMESTAMP(6) WHERE id=?",decision,actor.enterpriseId(),reason,decision,id);voiceHistory(actor,id,expected+1,decision,reason);audit(actor,"VOICEPRINT_REVIEWED",id,expected+1);return voice(id);});
 }
 public Map<String,Object> revoke(Actor actor,String id,String key,long expected,String reason){
  id(id);expected(expected);reason(reason);return command(actor,key,"VOICE_REVOKE",List.of(id,expected,reason),false,()->{var row=lockedVoice(id);if(!actor.enterpriseId().equals(row.get("subject_id")))throw new AccessDeniedException();if(expected!=((Number)row.get("revision")).longValue()||"REVOKED".equals(row.get("state")))throw new Conflict();j.update("UPDATE governed_voiceprint SET state='REVOKED',revision=revision+1,encrypted_embedding=NULL,review_reason=?,updated_at=UTC_TIMESTAMP(6) WHERE id=?",reason,id);j.update("UPDATE meeting_voiceprint_application SET encrypted_embedding=NULL WHERE id=?",id);voiceHistory(actor,id,expected+1,"REVOKED",reason);audit(actor,"VOICEPRINT_REVOKED",id,expected+1);return voice(id);});
 }
 private void voiceHistory(Actor actor,String id,long revision,String state,String reason){j.update("INSERT INTO governed_voiceprint_history(voiceprint_id,revision,actor_id,state,reason) VALUES (?,?,?,?,?)",id,revision,actor.enterpriseId(),state,reason);}
 private Map<String,Object> lockedVoice(String id){var rows=j.queryForList("SELECT * FROM governed_voiceprint WHERE id=? FOR UPDATE",id);if(rows.size()!=1)throw new AccessDeniedException();return rows.getFirst();}
 private Map<String,Object> voice(String id){return j.queryForMap("SELECT "+VOICE+" FROM governed_voiceprint WHERE id=?",id);}
 public Map<String,Object> capabilities(Actor actor){return tx.required(()->{active(actor);boolean reviewer=admin(actor);var config=currentConfig();return Map.of("reviewer",reviewer,"voiceprintPurpose","SPEAKER_CANDIDATE","modelVersion",config.modelVersion(),"promptVersion",config.promptVersion(),"actions",Map.of("enrollSelf",true,"submitFeedback",true,"reviewCorpus",reviewer,"reviewVoiceprints",reviewer,"manageDatasets",reviewer,"runEvaluations",reviewer,"reviewEvaluations",reviewer,"manageConfiguration",reviewer,"publishConfiguration",reviewer),"datasetSampleLimit",50);});}
 public List<Map<String,Object>> voices(Actor actor){return tx.required(()->{active(actor);boolean reviewer=admin(actor);return j.queryForList("SELECT "+VOICE+" FROM governed_voiceprint WHERE "+(reviewer?"1=1":"subject_id=?")+" ORDER BY created_at DESC,id DESC LIMIT 100",reviewer?new Object[0]:new Object[]{actor.enterpriseId()});});}
 public List<VoiceprintService.Candidate> match(Actor actor,byte[] wav){
  var config=tx.required(()->{requireAdmin(actor);return currentConfig();});if(config.voiceThreshold()==null)throw new IllegalArgumentException("No calibrated matching configuration released");var input=model.embed(wav,config.modelVersion());
  return tx.required(()->{requireAdmin(actor);if(!currentConfig().equals(config))throw new Conflict();var rows=j.queryForList("SELECT v.*,i.status identity_status FROM governed_voiceprint v JOIN enterprise_identity i ON i.enterprise_id=v.subject_id WHERE v.state='APPROVED' AND v.expires_at>UTC_TIMESTAMP(6) AND v.model_version=? AND i.status='ACTIVE' AND NOT EXISTS(SELECT 1 FROM meeting_voiceprint_application a JOIN meeting m ON m.id=a.meeting_id WHERE a.id=v.id AND (a.state<>'ACCEPTED' OR m.lifecycle<>'ACTIVE' OR m.governance_state<>'ACTIVE')) ORDER BY v.id LIMIT 101 FOR SHARE",input.modelVersion());if(rows.size()>100)throw new NotAvailable();var entries=new ArrayList<VoiceprintService.Entry>();for(var row:rows){String id=(String)row.get("id"),subject=(String)row.get("subject_id"),version=(String)row.get("model_version");int dim=((Number)row.get("dimension")).intValue();var vector=crypto.decrypt(aad(id,subject,version,dim),version,dim,(byte[])row.get("encrypted_embedding"));entries.add(new VoiceprintService.Entry(id,subject,(String)row.get("state"),"ACTIVE".equals(row.get("identity_status")),instant(row.get("expires_at")),vector));}return new VoiceprintService().match(input,entries,config.voiceThreshold(),Instant.now());});
 }
 public Map<String,Object> dataset(Actor actor,String key,String version,List<Sample> samples){
  ama.contract.GovernanceContracts.token(version);samples=List.copyOf(samples);if(samples.isEmpty()||samples.size()>50||samples.stream().map(Sample::id).distinct().count()!=samples.size()||write(samples).length()>8*1024*1024)throw new IllegalArgumentException("1 to 50 unique bounded samples required");String body=write(samples);
  return command(actor,key,"DATASET_CREATE",List.of(version,body),true,()->{if(!j.queryForList("SELECT id FROM governance_dataset WHERE version=?",String.class,version).isEmpty())throw new Conflict();String id=UUID.randomUUID().toString();j.update("INSERT INTO governance_dataset(id,version,owner_id,samples_json,content_sha) VALUES (?,?,?,?,?)",id,version,actor.enterpriseId(),body,sha(body.getBytes(java.nio.charset.StandardCharsets.UTF_8)));audit(actor,"DATASET_CREATED",id,0);return Map.of("id",id,"version",version);});
 }
 public List<Map<String,Object>> datasets(Actor actor){return tx.required(()->{requireAdmin(actor);return j.queryForList("SELECT id,version,content_sha contentSha,sample_count sampleCount FROM governance_dataset FORCE INDEX (operations_dataset_history) ORDER BY created_at DESC,id DESC LIMIT 100");});}
 public Map<String,Object> evaluate(Actor actor,String key,String dataset,ModelConfig config){
  id(dataset);return command(actor,key,"EVALUATE",List.of(dataset,config),true,()->{if(j.queryForObject("SELECT COUNT(*) FROM governance_dataset WHERE id=?",Integer.class,dataset)!=1)throw new IllegalArgumentException("Dataset version required");GovernanceCatalog.require(config);String id=UUID.randomUUID().toString();j.update("INSERT INTO governance_evaluation(id,dataset_id,config_json,actor_id,state) VALUES (?,?,?,?,'PENDING')",id,dataset,write(config),actor.enterpriseId());audit(actor,"EVALUATION_QUEUED",id,0);return Map.of("id",id,"state","PENDING");});
 }
 public List<Map<String,Object>> evaluations(Actor actor){return tx.required(()->{requireAdmin(actor);return j.queryForList("SELECT e.id,d.version datasetVersion,e.state,e.review_reason reviewReason FROM governance_evaluation e JOIN governance_dataset d ON d.id=e.dataset_id ORDER BY e.created_at DESC,e.id DESC LIMIT 100");});}
 public void processEvaluation(){
  // One bounded sample per claim. Mail uses a different executor and cannot be held by a dataset.
  if(j.queryForObject("SELECT COUNT(*) FROM recording_session WHERE state IN ('OPEN','PAUSED') AND writer_lease_expires_at>UTC_TIMESTAMP(6)",Integer.class)>0||j.queryForObject("SELECT COUNT(*) FROM speech_execution WHERE state IN ('RESERVED','UNKNOWN')",Integer.class)>0)return;
  String lease=UUID.randomUUID().toString();var run=tx.required(()->{var rows=j.queryForList("SELECT * FROM governance_evaluation WHERE state IN ('PENDING','RUNNING') AND (lease_until IS NULL OR lease_until<UTC_TIMESTAMP(6)) ORDER BY created_at,id LIMIT 1 FOR UPDATE SKIP LOCKED");if(rows.isEmpty())return null;var row=rows.getFirst();j.update("UPDATE governance_evaluation SET state='RUNNING',lease_owner=?,lease_until=TIMESTAMPADD(SECOND,60,UTC_TIMESTAMP(6)) WHERE id=?",lease,row.get("id"));return row;});if(run==null)return;
  String id=(String)run.get("id");var config=read((String)run.get("config_json"),ModelConfig.class);var samples=read(j.queryForObject("SELECT CAST(samples_json AS CHAR) FROM governance_dataset WHERE id=?",String.class,run.get("dataset_id")),Sample[].class);
  var existing=new HashSet<>(j.queryForList("SELECT sample_id FROM governance_evaluation_sample WHERE run_id=?",String.class,id));var next=Arrays.stream(samples).filter(s->!existing.contains(s.id())).findFirst();
  boolean live=tx.required(()->{var identities=j.queryForList("SELECT status FROM enterprise_identity WHERE enterprise_id=? FOR SHARE",String.class,run.get("actor_id"));boolean allowed=identities.equals(List.of("ACTIVE"))&&!j.queryForList("SELECT role FROM role_assignment WHERE enterprise_id=? AND role='PLATFORM_ADMIN' FOR SHARE",String.class,run.get("actor_id")).isEmpty();if(!allowed)j.update("UPDATE governance_evaluation SET state='CANCELLED',lease_owner=NULL,lease_until=NULL,finished_at=UTC_TIMESTAMP(6) WHERE id=? AND lease_owner=?",id,lease);return allowed;});if(!live)return;
  if(next.isPresent()){
   var sample=next.get();long started=System.nanoTime();SampleResult result;
   try{result=model.evaluate(resolve(sample),config);if(!result.id().equals(sample.id()))throw new IllegalArgumentException("Wrong result identity");}
   catch(RuntimeException failure){result=new SampleResult(sample.id(),false,0,failure instanceof IllegalArgumentException?"INVALID_INPUT_OR_REFERENCE":"MODEL_OR_INPUT_UNAVAILABLE",null,Map.of(),(System.nanoTime()-started)/1_000_000,config.modelVersion(),config.promptVersion(),false);}final var outcome=result;
   tx.required(()->{var rows=j.queryForList("SELECT id FROM governance_evaluation WHERE id=? AND lease_owner=? AND state='RUNNING' AND lease_until>UTC_TIMESTAMP(6) FOR UPDATE",id,lease);if(rows.isEmpty())return null;
    boolean allowed="ACTIVE".equals(j.queryForObject("SELECT status FROM enterprise_identity WHERE enterprise_id=? FOR SHARE",String.class,run.get("actor_id")))&&!j.queryForList("SELECT role FROM role_assignment WHERE enterprise_id=? AND role='PLATFORM_ADMIN' FOR SHARE",String.class,run.get("actor_id")).isEmpty();
    if(!allowed){j.update("UPDATE governance_evaluation SET state='CANCELLED',lease_owner=NULL,lease_until=NULL,finished_at=UTC_TIMESTAMP(6) WHERE id=?",id);return null;}
    j.update("INSERT INTO governance_evaluation_sample(run_id,sample_id,result_json) VALUES (?,?,?) ON DUPLICATE KEY UPDATE run_id=governance_evaluation_sample.run_id",id,sample.id(),write(outcome));return null;});
  }
  tx.required(()->{int count=j.queryForObject("SELECT COUNT(*) FROM governance_evaluation_sample WHERE run_id=?",Integer.class,id);j.update("UPDATE governance_evaluation SET state=?,lease_owner=NULL,lease_until=NULL,finished_at=IF(?='COMPLETED',UTC_TIMESTAMP(6),NULL) WHERE id=? AND lease_owner=? AND state='RUNNING' AND lease_until>UTC_TIMESTAMP(6)",count==samples.length?"COMPLETED":"RUNNING",count==samples.length?"COMPLETED":"RUNNING",id,lease);return null;});
 }
 private Sample resolve(Sample sample){return new Sample(sample.id(),sample.kind(),resolve(sample.input()),sample.input2()==null?null:resolve(sample.input2()),sample.expected());}
 private String resolve(String value){if(!value.startsWith("asset:"))return value;String id=value.substring(6);id(id);byte[] wav=j.queryForObject("SELECT wav FROM governance_sample_asset WHERE id=?",byte[].class,id);if(wav==null)throw new IllegalArgumentException("Sample asset unavailable");return Base64.getEncoder().encodeToString(wav);}
 public Map<String,Object> evaluation(Actor actor,String id){id(id);return tx.required(()->{requireAdmin(actor);return evaluation(id);});}
 private Map<String,Object> evaluation(String id){var row=j.queryForMap("SELECT e.id,e.state,CAST(e.config_json AS CHAR) configuration,d.version datasetVersion,e.review_reason reviewReason,e.reviewed_by reviewedBy,JSON_LENGTH(d.samples_json) sampleCount FROM governance_evaluation e JOIN governance_dataset d ON d.id=e.dataset_id WHERE e.id=?",id);var results=j.queryForList("SELECT CAST(result_json AS CHAR) FROM governance_evaluation_sample WHERE run_id=? ORDER BY sample_id",String.class,id).stream().map(s->read(s,SampleResult.class)).toList();int total=((Number)row.remove("sampleCount")).intValue();int ok=(int)results.stream().filter(SampleResult::succeeded).count();row.put("metrics",Map.of("sampleCount",total,"succeeded",ok,"failed",results.size()-ok,"pending",total-results.size(),"score",results.stream().mapToDouble(SampleResult::score).sum()/total));row.put("results",results);row.put("configuration",read((String)row.get("configuration"),ModelConfig.class));return row;}
 public Map<String,Object> reviewEvaluation(Actor actor,String id,String key,String reason){id(id);reason(reason);return command(actor,key,"EVALUATION_REVIEW",List.of(id,reason),true,()->{var run=j.queryForMap("SELECT actor_id FROM governance_evaluation WHERE id=? FOR UPDATE",id);if(actor.enterpriseId().equals(run.get("actor_id")))throw new AccessDeniedException();if(j.update("UPDATE governance_evaluation SET review_reason=?,reviewed_by=? WHERE id=? AND state='COMPLETED' AND review_reason IS NULL",reason,actor.enterpriseId(),id)!=1)throw new Conflict();audit(actor,"EVALUATION_REVIEWED",id,0);return Map.of("id",id,"reviewReason",reason);});}
 public Map<String,Object> release(Actor actor,String key,long expected,String run,ModelConfig config,String reason){id(run);expected(expected);reason(reason);return command(actor,key,"CONFIG_RELEASE",List.of(expected,run,config,reason),true,()->{
  long current=j.queryForObject("SELECT revision FROM governance_configuration ORDER BY revision DESC LIMIT 1 FOR UPDATE",Long.class);if(current!=expected)throw new Conflict();
  var evaluation=j.queryForMap("SELECT * FROM governance_evaluation WHERE id=? FOR SHARE",run);var candidates=j.queryForList("SELECT * FROM governance_candidate WHERE id=? AND evaluation_id=? AND state='APPROVED' FOR SHARE",evaluation.get("candidate_id"),run);
  if(candidates.size()!=1||!"COMPLETED".equals(evaluation.get("state"))||!config.equals(read((String)evaluation.get("config_json"),ModelConfig.class)))throw new IllegalArgumentException("Approved exact candidate evaluation required");
  var candidate=candidates.getFirst();String approver=(String)candidate.get("approved_by");
  if(approver==null||approver.equals(candidate.get("creator_id"))||approver.equals(evaluation.get("actor_id"))||!approver.equals(evaluation.get("reviewed_by"))||!config.equals(read((String)candidate.get("configuration"),ModelConfig.class))||((Number)candidate.get("revision")).longValue()!=((Number)evaluation.get("candidate_revision")).longValue()+1)throw new IllegalArgumentException("Independent approval of exact candidate required");
  if(!"ACTIVE".equals(j.queryForObject("SELECT status FROM enterprise_identity WHERE enterprise_id=? FOR SHARE",String.class,approver))||j.queryForList("SELECT role FROM role_assignment WHERE enterprise_id=? AND role='PLATFORM_ADMIN' FOR SHARE",String.class,approver).isEmpty())throw new AccessDeniedException();
  if(!new JdbcGovernanceWorkbench(j.getDataSource(),tx,access,this).assess(run).eligible())throw new IllegalArgumentException("Every kind must meet its frozen rules");
  j.update("INSERT INTO governance_configuration(revision,config_json,evaluation_id,actor_id,reason) VALUES (?,?,?,?,?)",expected+1,write(config),run,actor.enterpriseId(),reason);audit(actor,"CONFIGURATION_RELEASED",run,expected+1);return Map.of("revisionToken",Long.toString(expected+1),"configuration",config);
 });}
 public Map<String,Object> rollback(Actor actor,String key,long expected,long target,String reason){return tx.required(()->{requireAdmin(actor);throw new IllegalArgumentException("Rollback must create an independently reviewed candidate");});}
 public Map<String,Object> configuration(Actor actor){return tx.required(()->{requireAdmin(actor);return Map.of("revisionToken",Long.toString(j.queryForObject("SELECT MAX(revision) FROM governance_configuration",Long.class)),"configuration",currentConfig(),"history",j.queryForList("SELECT CAST(revision AS CHAR) revisionToken,evaluation_id evaluationId,CAST(rollback_of AS CHAR) rollbackOf,reason,DATE_FORMAT(created_at,'%Y-%m-%dT%H:%i:%s.%fZ') createdAt FROM governance_configuration ORDER BY revision DESC LIMIT 100"));});}
 private ModelConfig currentConfig(){return read(j.queryForObject("SELECT CAST(config_json AS CHAR) FROM governance_configuration ORDER BY revision DESC LIMIT 1",String.class),ModelConfig.class);}
 private static Instant instant(Object value){return value instanceof Timestamp t?t.toInstant():((java.time.LocalDateTime)value).toInstant(ZoneOffset.UTC);}
 private static String aad(String id,String subject,String model,int dimension){return id+":"+subject+":"+model+":"+dimension;}
 private static String sha(byte[] bytes){try{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes));}catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}}
 public void cleanExpired(){j.update("UPDATE governed_voiceprint SET encrypted_embedding=NULL WHERE encrypted_embedding IS NOT NULL AND expires_at<=UTC_TIMESTAMP(6)");}
}
